<section class="container page-section"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/account">Account</a><span>/</span><span>Orders</span></div><span class="eyebrow">ORDER HISTORY</span><h1>Your orders</h1><?php if(!$orders): ?><div class="empty-state"><div class="empty-icon">▤</div><h2>No orders yet</h2><p>Your orders will show up here after checkout.</p><a class="btn btn-primary" href="/products">Start shopping</a></div><?php else: ?><div class="orders-list"><?php foreach($orders as $order): ?><a class="order-row" href="/order?id=<?= (int)$order['id'] ?>"><div><small>ORDER PLACED</small><strong><?= e(date('M j, Y',strtotime($order['created_at']))) ?></strong></div><div><small>ORDER NUMBER</small><strong><?= e($order['order_number']) ?></strong></div><div><small>STATUS</small><span class="status-pill"><?= e(ucfirst($order['status'])) ?></span></div><div><small>TOTAL</small><strong><?= money($order['total']) ?></strong></div><span>→</span></a><?php endforeach; ?></div><?php endif; ?></section>